// Verify the signature over the EXACT bytes received. The app signs the
// serialized body it sends, so re-serializing here before hashing would
// produce a different digest and every event would look forged.
const crypto = require('crypto');

const SECRET = 'set-me-to-WEBHOOK_SECRET';

const raw = $input.first().binary
  ? Buffer.from($input.first().binary.data.data, 'base64').toString('utf8')
  : JSON.stringify($input.first().json.body);

const provided = $input.first().json.headers['x-webhook-signature'] || '';
const expected = 'sha256=' + crypto.createHmac('sha256', SECRET).update(raw).digest('hex');

// timingSafeEqual throws on a length mismatch, which is itself a failed check.
let verified = false;
try {
  verified = crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(provided));
} catch (error) {
  verified = false;
}

const event = JSON.parse(raw);
return [{ json: { verified, ...event } }];

// Whatever you want to happen when a learner finishes a take: a Slack
// message, a row in a sheet, a nudge if the score dropped. The event carries
// everything needed to decide without calling back into the app.
const { payload, event_type, correlation_id } = $input.first().json;

return [{
  json: {
    event_type,
    correlation_id,
    attempt_id: payload.attempt_id,
    score_percent: Math.round((payload.overall_score ?? 0) * 100),
    exp_awarded: payload.exp_awarded,
    needs_review: payload.status === 'needs_review',
  },
}];

// A signature that does not verify is either a misconfigured secret or
// something you want to know about. Never silently drop it.
return [{ json: { rejected: true, reason: 'signature did not verify' } }];
